-- Callboard Cache rewards.
--
-- A Callboard Cache names its content, and every item CoA ties to that content carries it as a
-- source tag in `item_template`.`description` ('@Heroic Dungeon@', '@Heroic Molten Core@', ...).
-- Difficulty is part of that tag: the normal row of an item carries none, while '@Heroic <raid>@',
-- '@Mythic <raid>@' and '@Ascended <raid>@' are separate rows of the same item at a higher item
-- level. A raid cache holds the normal row of every item tagged with its own raid, so a Zul'Gurub
-- Cache never pays a Naxxramas item and no cache ever pays a Heroic, Mythic or Ascended copy. A
-- dungeon cache holds the items tagged with its dungeon tier, which is CoA's own dungeon set. Items
-- Ascension retired ('This Token has been deprecated ...') are in no pool: their own text says they
-- are no longer a reward, and the raids they used to belong to still list them in their loot.
--
-- StatType is the item's dominant stat, 1 Strength, 2 Agility, 3 Intellect, 4 Spirit, 5 Misc.
-- ArmorClass is the item's subclass, which identifies its armour or weapon class.

DROP TABLE IF EXISTS `ascension_callboard_cache_reward`;
CREATE TABLE `ascension_callboard_cache_reward` (
  `CacheItemId` INT UNSIGNED NOT NULL,
  `RewardItemId` INT UNSIGNED NOT NULL,
  `RewardItemLevel` SMALLINT UNSIGNED NOT NULL,
  `StatType` TINYINT UNSIGNED NOT NULL DEFAULT 5,
  `ArmorClass` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`CacheItemId`, `RewardItemId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `ascension_callboard_cache_reward`;
